// 反例（对 String 调用会抛 NSException，try? 接不住）：
// let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any]

// 正解：用 JSONEncoder 包一层数组再剥壳
func jsStr(_ s: String) -> String {
    guard let d = try? JSONEncoder().encode([s]),
          let arr = String(data: d, encoding: .utf8) else { return "\"\"" }
    // arr 形如 ["..."]，去掉首尾方括号即得合法 JSON 字符串字面量
    return String(arr.dropFirst().dropLast())
}

